import CloudkuMurotalAPI from './main.mjs';

class ESMTestRunner {
    constructor() {
        this.api = new CloudkuMurotalAPI();
        this.passed = 0;
        this.failed = 0;
        this.testResults = [];
    }

    async test(name, testFn) {
        process.stdout.write(`Testing ${name}... `);
        
        try {
            const result = await testFn();
            console.log('PASS');
            this.passed++;
            this.testResults.push({ name, status: 'PASS', result });
        } catch (error) {
            console.log('FAIL');
            console.log(`   Error: ${error.message}`);
            this.failed++;
            this.testResults.push({ name, status: 'FAIL', error: error.message });
        }
    }

    async runBasicTests() {
        console.log('Basic Module Tests\n');

        await this.test('Import Check', async () => {
            if (typeof CloudkuMurotalAPI !== 'function') {
                throw new Error('Import failed');
            }
            return 'Import successful';
        });

        await this.test('Instance Creation', async () => {
            const api = new CloudkuMurotalAPI();
            if (!api.baseURL) {
                throw new Error('Instance creation failed');
            }
            return `Base URL: ${api.baseURL}`;
        });

        await this.test('User Agent Check', async () => {
            if (!this.api.userAgent || this.api.userAgent !== 'cloudku-murotal/2.0.0') {
                throw new Error('User agent not set correctly');
            }
            return `User Agent: ${this.api.userAgent}`;
        });
    }

    async runMethodTests() {
        console.log('\nMethod Existence Tests\n');

        const methods = [
            'getAllCities',
            'searchCities',
            'getPrayerTimesByDate',
            'getPrayerTimesByMonth',
            'getCurrentHijriDate',
            'getHijriDateByGregorian',
            'getRandomAsmaulHusna',
            'getAllAsmaulHusna',
            'getAsmaulHusnaByNumber',
            'getSurahList',
            'getSurahByNumber',
            'getRandomSurah',
            'getAyahByNumber',
            'getSingleAyah',
            'getAyahRange',
            'getSurahAyahRange',
            'getRandomAyah',
            'getJuzByNumber',
            'getAllThemes',
            'getAyahByTheme',
            'getDoaSources',
            'searchDua',
            'getRandomDua',
            'getRandomHadithArbain',
            'getRandomHadithBukhari'
        ];

        for (const method of methods) {
            await this.test(`Method ${method}`, async () => {
                if (typeof this.api[method] !== 'function') {
                    throw new Error(`Method ${method} not found`);
                }
                return `Method exists and is callable`;
            });
        }
    }

    async runAPITests() {
        console.log('\nAPI Request Tests\n');

        await this.test('Get All Cities', async () => {
            const result = await this.api.getAllCities();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return `Response received with ${Array.isArray(result.data) ? result.data.length : 'unknown'} items`;
        });

        await this.test('Get Current Hijri Date', async () => {
            const result = await this.api.getCurrentHijriDate();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Hijri date retrieved successfully';
        });

        await this.test('Get Random Asmaul Husna', async () => {
            const result = await this.api.getRandomAsmaulHusna();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Random Asmaul Husna retrieved successfully';
        });

        await this.test('Get Surah List', async () => {
            const result = await this.api.getSurahList();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return `Surah list retrieved with ${Array.isArray(result.data) ? result.data.length : 'unknown'} items`;
        });

        await this.test('Get Random Ayah', async () => {
            const result = await this.api.getRandomAyah();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Random Ayah retrieved successfully';
        });

        await this.test('Get All Themes', async () => {
            const result = await this.api.getAllThemes();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Themes retrieved successfully';
        });

        await this.test('Get Random Dua', async () => {
            const result = await this.api.getRandomDua();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Random Dua retrieved successfully';
        });

        await this.test('Get Random Hadith Arbain', async () => {
            const result = await this.api.getRandomHadithArbain();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Random Hadith Arbain retrieved successfully';
        });

        await this.test('Get Random Hadith Bukhari', async () => {
            const result = await this.api.getRandomHadithBukhari();
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Random Hadith Bukhari retrieved successfully';
        });
    }

    async runParameterTests() {
        console.log('\nParameter Validation Tests\n');

        await this.test('Search Cities with Query', async () => {
            const result = await this.api.searchCities('jakarta');
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'City search with parameter successful';
        });

        await this.test('Search Cities without Query (should fail)', async () => {
            try {
                await this.api.searchCities();
                throw new Error('Should have thrown an error for missing query');
            } catch (error) {
                if (error.message.includes('Search query is required')) {
                    return 'Validation working correctly';
                }
                throw error;
            }
        });

        await this.test('Get Surah by Number', async () => {
            const result = await this.api.getSurahByNumber(1);
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Surah retrieval by number successful';
        });

        await this.test('Get Hijri Date by Gregorian', async () => {
            const result = await this.api.getHijriDateByGregorian('2024-01-01');
            if (!result || typeof result !== 'object') {
                throw new Error('Invalid response format');
            }
            return 'Hijri date conversion successful';
        });
    }

    async runDateFormatTests() {
        console.log('\nDate Formatting Tests\n');

        await this.test('Date Format Function', async () => {
            const formatted = this.api.formatDate('2008-12-28');
            if (formatted !== '28-12-2008') {
                throw new Error(`Expected '28-12-2008', got '${formatted}'`);
            }
            return 'Date formatting working correctly';
        });

        await this.test('Invalid Date Format', async () => {
            const result = this.api.formatDate('invalid-date');
            if (result !== 'invalid-date') {
                throw new Error('Should return original string for invalid dates');
            }
            return 'Invalid date handling working correctly';
        });

        await this.test('Null Date Format', async () => {
            const result = this.api.formatDate(null);
            if (result !== null) {
                throw new Error('Should return null for null input');
            }
            return 'Null date handling working correctly';
        });
    }

    async runTests() {
        console.log('ESM Module Complete Test Suite\n');
        console.log('='.repeat(50));
        
        try {
            await this.runBasicTests();
            await this.runMethodTests();
            await this.runAPITests();
            await this.runParameterTests();
            await this.runDateFormatTests();
        } catch (error) {
            console.log('Critical error during testing:', error.message);
        }

        console.log('\n' + '='.repeat(50));
        console.log(`Test Results: ${this.passed} passed, ${this.failed} failed`);
        
        if (this.failed === 0) {
            console.log('All tests passed! ESM module working correctly.');
        } else {
            console.log('Some tests failed. Please check the errors above.');
            
            console.log('\nFailed Tests:');
            this.testResults
                .filter(test => test.status === 'FAIL')
                .forEach(test => {
                    console.log(`- ${test.name}: ${test.error}`);
                });
        }

        console.log('\nTest completed.');
        process.exit(this.failed > 0 ? 1 : 0);
    }
}

const runner = new ESMTestRunner();
runner.runTests().catch(error => {
    console.error('Test runner failed:', error);
    process.exit(1);
});